#!/usr/bin/env python3
"""Check redirect hostnames and write a GitHub Actions DNS summary."""

from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor
import ipaddress
import os
from pathlib import Path
import re
import subprocess
import sys

ROOT = Path(__file__).resolve().parent.parent
RECORD_TYPES = ("CNAME", "A", "AAAA")


def hostnames(directory):
    hosts = set()
    for path in directory.glob("*.json"):
        hostname = path.name[:-5]
        hosts.add(hostname)
        # Match the aliases generated by make-caddy.py.
        if hostname.count(".") == 1:
            hosts.add(f"www.{hostname}")
    return sorted(hosts)


def lookup(hostname, record_type):
    try:
        result = subprocess.run(
            ["dig", "+time=3", "+tries=2", "+noall", "+comments", "+answer", hostname, record_type],
            capture_output=True, text=True, timeout=10, check=False,
        )
    except (OSError, subprocess.TimeoutExpired) as error:
        return [], str(error)
    status = re.search(r"status: (\w+)", result.stdout)
    if result.returncode or not status:
        return [], result.stderr.strip() or "DNS lookup failed"
    if status.group(1) not in ("NOERROR", "NXDOMAIN"):
        return [], f"DNS status {status.group(1)}"
    records = []
    for line in result.stdout.splitlines():
        fields = line.split()
        if len(fields) >= 5 and fields[3] == record_type:
            records.append(fields[4].rstrip("."))
    return sorted(set(records)), None


def check_host(hostname):
    records, errors = {}, []
    for record_type in RECORD_TYPES:
        records[record_type], error = lookup(hostname, record_type)
        if error:
            errors.append(f"{record_type}: {error}")
    return hostname, records, errors


def code(value):
    # Hostnames and resolver errors are external input; keep them inside the cell.
    return "`" + str(value).replace("`", "'").replace("|", "\\|").replace("\n", " ") + "`"


def report(results):
    groups = defaultdict(list)
    missing, errors = [], []
    for hostname, records, failures in results:
        if failures:
            errors.append((hostname, "; ".join(failures)))
        if not any(records.values()) and not failures:
            missing.append(hostname)
        for address in set(records["A"] + records["AAAA"]):
            groups[address].append((hostname, records["CNAME"]))
    lines = ["# DNS report", "", f"Checked **{len(results)}** hostnames; **{len(missing)}** have no CNAME, A or AAAA record; **{len(errors)}** had lookup errors.", "", "A hostname with a CNAME but no resolved IP passes the record-presence check and is listed separately below. This report does not verify that an IP is the expected destination.", ""]
    for address in sorted(groups, key=lambda value: (ipaddress.ip_address(value).version, ipaddress.ip_address(value))):
        lines += [f"## {code(address)}", "", "| Hostname | CNAME |", "| --- | --- |"]
        for hostname, cnames in sorted(groups[address]):
            lines.append(f"| {code(hostname)} | {', '.join(map(code, cnames)) or '—'} |")
        lines.append("")
    cname_only = [(host, records["CNAME"]) for host, records, _ in results if records["CNAME"] and not (records["A"] or records["AAAA"])]
    if cname_only:
        lines += ["## CNAME without resolved IP", "", "| Hostname | CNAME |", "| --- | --- |"]
        lines += [f"| {code(host)} | {', '.join(map(code, cnames))} |" for host, cnames in cname_only]
        lines.append("")
    if missing:
        lines += ["## No DNS records", ""] + [f"- {code(host)}" for host in missing] + [""]
    if errors:
        lines += ["## Lookup errors", "", "| Hostname | Error |", "| --- | --- |"]
        lines += [f"| {code(host)} | {code(error)} |" for host, error in errors]
        lines.append("")
    return "\n".join(lines), bool(missing or errors)


def main():
    hosts = hostnames(ROOT / "domains")
    if not hosts:
        print("No domain JSON files found", file=sys.stderr)
        return 1
    with ThreadPoolExecutor(max_workers=20) as executor:
        results = list(executor.map(check_host, hosts))
    summary, failed = report(results)
    print(summary)
    if os.environ.get("GITHUB_STEP_SUMMARY"):
        with open(os.environ["GITHUB_STEP_SUMMARY"], "a", encoding="utf-8") as output:
            output.write(summary + "\n")
    return int(failed)


if __name__ == "__main__":
    sys.exit(main())
